example.snippet:
package main

import (
	"context"

	"dagger/my-module/internal/dagger"
)

type MyModule struct{}

// Create Redis service and client
func (m *MyModule) Redis(ctx context.Context) *dagger.Container {
	redisSrv := dag.Container().
		From("redis").
		WithExposedPort(6379).
		WithMountedCache("/data", dag.CacheVolume("my-redis")).
		WithWorkdir("/data").
		AsService(dagger.ContainerAsServiceOpts{UseEntrypoint: true})

	redisCLI := dag.Container().
		From("redis").
		WithServiceBinding("redis-srv", redisSrv).
		WithEntrypoint([]string{"redis-cli", "-h", "redis-srv"})

	return redisCLI
}

var execOpts = dagger.ContainerWithExecOpts{
	UseEntrypoint: true,
}

// Set key and value in Redis service
func (m *MyModule) Set(
	ctx context.Context,
	// The cache key to set
	key string,
	// The cache value to set
	value string,
) (string, error) {
	return m.Redis(ctx).
		WithExec([]string{"set", key, value}, execOpts).
		WithExec([]string{"save"}, execOpts).
		Stdout(ctx)
}

// Get value from Redis service
func (m *MyModule) Get(
	ctx context.Context,
	// The cache key to get
	key string,
) (string, error) {
	return m.Redis(ctx).
		WithExec([]string{"get", key}, execOpts).
		Stdout(ctx)
}

from typing import Annotated
import dagger from dagger import Doc, dag, function, object_type
@object_type class MyModule: @function def redis(self) -> dagger.Container: """Create Redis service and client""" redis_srv = ( dag.container() .from_("redis") .with_exposed_port(6379) .with_mounted_cache("/data", dag.cache_volume("my-redis")) .with_workdir("/data") .as_service(use_entrypoint=True) )
# create Redis client container redis_cli = ( dag.container() .from_("redis") .with_service_binding("redis-srv", redis_srv) .with_entrypoint(["redis-cli", "-h", "redis-srv"]) )
return redis_cli
@function async def set( self, key: Annotated[str, Doc("The cache key to set")], value: Annotated[str, Doc("The cache value to set")], ) -> str: """Set key and value in Redis service""" return ( await self.redis() .with_exec(["set", key, value], use_entrypoint=True) .with_exec(["save"], use_entrypoint=True) .stdout() )
@function async def get( self, key: Annotated[str, Doc("The cache key to get")], ) -> str: """Get value from Redis service""" return await self.redis().with_exec(["get", key], use_entrypoint=True).stdout()

import { dag, object, func, Container } from "@dagger.io/dagger"

@object()
class MyModule {
  /**
   * Create Redis service and client
   */
  @func()
  redis(): Container {
    const redisSrv = dag
      .container()
      .from("redis")
      .withExposedPort(6379)
      .withMountedCache("/data", dag.cacheVolume("my-redis"))
      .withWorkdir("/data")
      .asService({ useEntrypoint: true })

    const redisCLI = dag
      .container()
      .from("redis")
      .withServiceBinding("redis-srv", redisSrv)
      .withEntrypoint(["redis-cli", "-h", "redis-srv"])

    return redisCLI
  }

  /**
   * Set key and value in Redis service
   */
  @func()
  async set(
    /**
     * The cache key to set
     */
    key: string,
    /**
     * The cache value to set
     */
    value: string,
  ): Promise {
    return await this.redis()
      .withExec(["set", key, value], { useEntrypoint: true })
      .withExec(["save"], { useEntrypoint: true })
      .stdout()
  }

  /**
   * Get value from Redis service
   */
  @func()
  async get(
    /**
     * The cache key to get
     */
    key: string,
  ): Promise {
    // set and save value
    return await this.redis()
      .withExec(["get", key], { useEntrypoint: true })
      .stdout()
  }
}
